$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot;$dll=Join-Path $root 'FireProject_Data\Managed\Scripts.dll';$bak="$dll.embr-smooth-motion.bak";$cecil=Join-Path $root '.modtools\ilspy\Mono.Cecil.dll'
if(!(Test-Path $bak)){Copy-Item $dll $bak};Add-Type -Path $cecil
$r=New-Object Mono.Cecil.DefaultAssemblyResolver;$r.AddSearchDirectory((Split-Path $dll));$p=New-Object Mono.Cecil.ReaderParameters;$p.AssemblyResolver=$r;$a=[Mono.Cecil.AssemblyDefinition]::ReadAssembly($dll,$p);$mod=$a.MainModule
$controller=$mod.Types|? FullName -eq 'RigidbodyFirstPersonController';$start=$controller.Methods|? Name -eq 'Start';$rb=$controller.Fields|? Name -eq 'm_RigidBody';$setter=$mod.ImportReference(($rb.FieldType.Resolve().Methods|? Name -eq 'set_interpolation'))
if(-not($start.Body.Instructions|?{$_.Operand -and $_.Operand.FullName -eq $setter.FullName})){$il=$start.Body.GetILProcessor();$ret=$start.Body.Instructions|? OpCode -eq ([Mono.Cecil.Cil.OpCodes]::Ret)|select -Last 1;$il.InsertBefore($ret,$il.Create([Mono.Cecil.Cil.OpCodes]::Ldarg_0));$il.InsertBefore($ret,$il.Create([Mono.Cecil.Cil.OpCodes]::Ldfld,$rb));$il.InsertBefore($ret,$il.Create([Mono.Cecil.Cil.OpCodes]::Ldc_I4_1));$il.InsertBefore($ret,$il.Create([Mono.Cecil.Cil.OpCodes]::Callvirt,$setter))}
$mouse=$mod.Types|? FullName -eq 'MouseLook';$look=$mouse.Methods|? Name -eq 'LookRotation';$helper=$mouse.Methods|? Name -eq 'ApplyCharacterRotation'
if(!$helper){$bits=[int][Mono.Cecil.MethodAttributes]::Private-bor[int][Mono.Cecil.MethodAttributes]::Static-bor[int][Mono.Cecil.MethodAttributes]::HideBySig;$helper=New-Object Mono.Cecil.MethodDefinition('ApplyCharacterRotation',([Mono.Cecil.MethodAttributes]$bits),$mod.TypeSystem.Void);$helper.Parameters.Add((New-Object Mono.Cecil.ParameterDefinition('character',[Mono.Cecil.ParameterAttributes]::None,$look.Parameters[0].ParameterType)));$helper.Parameters.Add((New-Object Mono.Cecil.ParameterDefinition('rotation',[Mono.Cecil.ParameterAttributes]::None,($mouse.Fields|? Name -eq 'm_CharacterTargetRot').FieldType)));$mouse.Methods.Add($helper)
$getRb=($start.Body.Instructions|?{$_.Operand-is[Mono.Cecil.GenericInstanceMethod]-and$_.Operand.FullName-match'GetComponent<UnityEngine.Rigidbody>'}|select -First 1).Operand;$move=$null;foreach($t in $mod.Types){foreach($m in $t.Methods){if($m.HasBody){$x=$m.Body.Instructions|?{$_.Operand-and$_.Operand.FullName-eq'System.Void UnityEngine.Rigidbody::MoveRotation(UnityEngine.Quaternion)'}|select -First 1;if($x){$move=$x.Operand;break}}};if($move){break}};if(!$getRb-or!$move){throw 'Could not resolve Rigidbody rotation methods.'};$h=$helper.Body.GetILProcessor();$h.Append($h.Create([Mono.Cecil.Cil.OpCodes]::Ldarg_0));$h.Append($h.Create([Mono.Cecil.Cil.OpCodes]::Callvirt,$getRb));$h.Append($h.Create([Mono.Cecil.Cil.OpCodes]::Ldarg_1));$h.Append($h.Create([Mono.Cecil.Cil.OpCodes]::Callvirt,$move));$h.Append($h.Create([Mono.Cecil.Cil.OpCodes]::Ret))}
$calls=@($look.Body.Instructions|?{$_.Operand-and$_.Operand.FullName-eq'System.Void UnityEngine.Transform::set_localRotation(UnityEngine.Quaternion)'});if($calls.Count-eq 4){foreach($n in 0,2){$calls[$n].OpCode=[Mono.Cecil.Cil.OpCodes]::Call;$calls[$n].Operand=$helper}}elseif($calls.Count-ne 2){throw 'Unexpected MouseLook layout.'}
$tmp="$dll.embr-smooth-motion.tmp";$a.Write($tmp);$a.Dispose();Move-Item $tmp $dll -Force;Write-Host 'Smooth movement mod installed.'
